package org.iets3.core.plugin.plugin;

/*Generated by MPS */

import com.intellij.openapi.diagnostic.Logger;
import org.jetbrains.mps.openapi.module.SRepository;
import jetbrains.mps.project.Project;
import javax.swing.JRootPane;
import javax.swing.SwingUtilities;
import com.intellij.openapi.progress.util.ProgressIndicatorBase;
import com.intellij.openapi.progress.ProgressManager;
import javax.swing.JFrame;
import jetbrains.mps.project.MPSProject;
import com.intellij.openapi.wm.WindowManager;
import com.intellij.openapi.wm.IdeFrame;
import jetbrains.mps.ide.project.ProjectHelper;
import java.awt.Window;
import java.awt.KeyboardFocusManager;
import java.awt.Frame;
import java.awt.Dialog;
import javax.swing.RootPaneContainer;

public class CommandWithMessage {
  private static final Logger LOG = Logger.getInstance(CommandWithMessage.class);

  public static void execute(final String message, final SRepository repository, final Runnable runnable) {
    // For callers without a project: the frame to paint on is the one of the project owning the repository.
    executeWithOverlay(message, repository, findRootPane(repository), runnable);
  }

  public static void execute(final String message, final Project project, final Runnable runnable) {
    executeWithOverlay(message, project.getRepository(), rootPaneOf(project), runnable);
  }

  private static void executeWithOverlay(final String message, final SRepository repository, final JRootPane pane, final Runnable runnable) {
    if (pane == null) {
      LOG.info("No showing frame to paint the progress on, running without it: " + message);
    }
    // Let the action finish and its menu close before the command blocks the UI thread.
    SwingUtilities.invokeLater(() -> {
      // The command runs on the UI thread, so the overlay is painted from a thread of its own.
      // The runnable can report its progress to ProgressManager.getInstance().getProgressIndicator().
      ProgressIndicatorBase indicator = new ProgressIndicatorBase();
      indicator.setText(message);
      Runnable inCommand = () -> repository.getModelAccess().executeCommand(() -> runnable.run());
      ProgressOverlay overlay = ProgressOverlay.start(message, indicator, pane);
      try {
        ProgressManager.getInstance().runProcess(inCommand, indicator);
      } finally {
        overlay.stop();
      }
    });
  }

  private static JRootPane rootPaneOf(Project project) {
    JFrame frame = ((project instanceof MPSProject ? WindowManager.getInstance().getFrame(((MPSProject) project).getProject()) : null));
    if (frame != null && frame.isShowing()) {
      return frame.getRootPane();
    }
    return fallbackRootPane();
  }

  private static JRootPane findRootPane(SRepository repository) {
    // Several projects can be open, each in a frame of its own.
    for (IdeFrame ideFrame : WindowManager.getInstance().getAllProjectFrames()) {
      MPSProject mpsProject = ProjectHelper.fromIdeaProject(ideFrame.getProject());
      if (mpsProject != null && mpsProject.getRepository() == repository) {
        return rootPaneOf(mpsProject);
      }
    }
    return fallbackRootPane();
  }

  private static JRootPane fallbackRootPane() {
    JRootPane active = activeRootPane();
    return ((active != null ? active : anyProjectRootPane()));
  }

  private static JRootPane activeRootPane() {
    Window window = KeyboardFocusManager.getCurrentKeyboardFocusManager().getActiveWindow();
    while (window != null && !(window instanceof Frame) && !(window instanceof Dialog)) {
      window = window.getOwner();
    }
    if (window instanceof RootPaneContainer && window.isShowing()) {
      return ((RootPaneContainer) window).getRootPane();
    }
    return null;
  }

  private static JRootPane anyProjectRootPane() {
    // No window is active while MPS is in the background, but its frames are still on the screen.
    for (IdeFrame ideFrame : WindowManager.getInstance().getAllProjectFrames()) {
      JFrame frame = WindowManager.getInstance().getFrame(ideFrame.getProject());
      if (frame != null && frame.isShowing()) {
        return frame.getRootPane();
      }
    }
    return null;
  }

}
